import type { BlastSafe } from '../../data/bosses'
import type { SiteMessages, TierMethod } from './pt'

/** Number in French format (`1 250`, `0,75`). */
const n = (v: number) => v.toLocaleString('fr-FR', { maximumFractionDigits: 2 })
/** French plural: 0 and 1 take the singular. */
const s = (count: number, one: string, many: string) => (Math.abs(count) < 2 ? one : many)
/** `a, b et c` */
const list = (items: readonly string[]) => (items.length < 2 ? items.join('') : `${items.slice(0, -1).join(', ')} et ${items.at(-1)}`)
/** `a, b ou c` */
const either = (items: readonly string[]) => (items.length < 2 ? items.join('') : `${items.slice(0, -1).join(', ')} ou ${items.at(-1)}`)

